import{_ as n,o as a,c as p,a5 as l}from"./chunks/framework.BPFk9-tb.js";const e="/assets/image-20250918230352310.BSLIKaf3.png",i="/assets/image-20250918230945685.BneVlxae.png",C=JSON.parse('{"title":"使用 AI 代码工具的一次升级","description":"","frontmatter":{"date":"2025-09-18T22:23:57","title":"使用 AI 代码工具的一次升级","categories":["教程100","写作","Solon","Solon 实用教程"],"tags":["教程100","写作","Solon","Solon 实用教程"]},"headers":[],"relativePath":"posts/course100/045.md","filePath":"posts/course100/045.md"}'),c={name:"posts/course100/045.md"};function t(o,s,r,d,g,u){return a(),p("div",null,[...s[0]||(s[0]=[l(`<p>最近找同事学习了些 AI 代码生成工具的使用，算是我的一次升级。先看下我生成代码的效果，从点击 「AI生成」开始的界面都是由 AI 生成的。如果觉得效果还可以的话，可以继续往下看。</p><blockquote><p>演示视频未随博客发布。</p></blockquote><p>作为一个普通开发人员，在使用先进的 AI 模型的时候，还是需要跨过几个门槛，比如网络，比如支付，比如封号等问题。我自己就是好不容易搞定支付之后，刚想用用 OpenAI 就被封号了。于是有一段时间虽然看到一些比较好的代码生成效果，自己也没有特别实践，导致自己使用 AI 变成工具非常原始。这次和同事聊天，他说到，自己写一个功能，自己就没写过代码。于是非常好奇他的工作流是怎么样的，然后过去学习了下，自己也验证了一番之后，果然有效。</p><p>我之前的使用方式是这样的，使用VS Code，然后 ROO CODE 插件，配置的是 DeepSeek。在使用时，直接在 Prompt 里面说要什么功能，然后等大模型生成，然后除了接受就是接受，最终完成的东西很大程度都没办法完成，需要自己继续修改。于是最终主体代码都是自己写，然后就是让ROO CODE 帮忙完成一些小功能，或者修复直接的报错的问题。</p><p>同事说，之前他也这么用，但是发现效果不好，后面就是让 AI 先整理自己的需求，然后提供方案，而不是直接提供代码。可以对方案提供质疑，然后进一步完善方案，方案完成后才让 AI 写代码。</p><p>在看了同事的直接操作之后，于是回家开始使用 Claud Code 插件，如果没有注册 Claude Code，可以使用下面的两种方式替代：</p><ol><li>使用 Claude 镜像站，<a href="https://www.aigocode.com/%EF%BC%8C%E5%90%8C%E4%BA%8B%E7%94%A8%E7%9A%84%E6%98%AF%E8%BF%99%E4%B8%AA%E6%96%B9%E5%BC%8F%E3%80%82" target="_blank" rel="noreferrer">https://www.aigocode.com/，同事用的是这个方式。</a></li><li>使用 Kimi 替代，我自己用的是这种方式。</li></ol><p>大家可以根据实际的情况自己选择，我这里简单描述下使用 Kimi 替代的操作。</p><ol><li>注册好 <a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">https://platform.moonshot.cn/</a> 账号，充值解除限速，并配置好 <code>API Key</code></li><li>安装好 Node.js</li><li>安装 Claude</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g @anthropic-ai/claude</span></span></code></pre></div><ol start="3"><li>配置环境变量，导出 <code>ANTHROPIC_BASE_URL</code> 和 <code>ANTHROPIC_AUTH_TOKEN</code></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 如果是其他操作系统，自己用对应的方式修改。</span></span>
<span class="line"><span>vi .zshrc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export ANTHROPIC_BASE_URL=https://api.moonshot.cn/anthropic</span></span>
<span class="line"><span>export ANTHROPIC_AUTH_TOKEN=sk-xxxxxxxxx</span></span></code></pre></div><ol start="4"><li>安装 VS Code 的 <code>Claude Code for VS Code</code> 插件</li><li>打开项目，通过/init 进行初始化。</li><li>接着可以通过对话的方式进行代码编写了。</li></ol><p>以下是演示的生成界面的主体过程（中间有关闭窗口，没有完整的记录），这个界面首先来自，<a href="https://mp.weixin.qq.com/s/tafopd82apfEtCk2DXU0sg%EF%BC%8C%E6%88%91%E6%9C%9F%E6%9C%9B%E7%9A%84%E6%98%AF%E9%80%9A%E8%BF%87" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/tafopd82apfEtCk2DXU0sg，我期望的是通过</a> AI 生成配置之后生成 CMS 站点的模版。这里主要就是生成配置页面的功能。</p><p>我的需求文档整理如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我现在想做为内容管理模块增加 AI 生成站点模板的功能。</span></span>
<span class="line"><span>通过模板管理的，[AI 模板] 进入对应的功能页面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>整个页面的核心就是两个部分一个是调整样式，一个是修改提示词，生成站点模板。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>首先可以在页面左侧对网页样式进行调整，比如主题色、辅助色、字体、大小、字间距、按钮样式等。为了简化网页样式的调整，需要有兜底方案，首先你可以选择预设的各种风格模板，另外的话可以点击「随机生成」按钮，点完所有的元素都会变化，用户可以多点几次挑选自己喜欢的配置。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可以在右侧预览，预览需要做了三个页面首页、产品、博客，方便在不同的页面内容上预览，通过 Tab 进行切换。另外预览的部分还支持手机、电脑、平板不同页面宽度的预览，需要支持夜间模式。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后用户可以设置补充默认的提示词内容，点击生成，把设置好的 JSON 和提示词调用 AI 接口生成对应的模板页面。</span></span></code></pre></div><p>可以让 Claude 之间生成到 doc 目录下，初步返回的内容如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 功能模块划分</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  核心模块：</span></span>
<span class="line"><span>  - 样式配置器（左侧）</span></span>
<span class="line"><span>  - 实时预览器（右侧）</span></span>
<span class="line"><span>  - AI生成引擎</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 样式配置器设计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  预设风格模板：</span></span>
<span class="line"><span>  - 现代简约（Linear风格）</span></span>
<span class="line"><span>  - 商务专业</span></span>
<span class="line"><span>  - 创意艺术</span></span>
<span class="line"><span>  - 科技感</span></span>
<span class="line"><span>  - 温暖亲和</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  样式配置维度：</span></span>
<span class="line"><span>  interface StyleConfig {</span></span>
<span class="line"><span>    theme: {</span></span>
<span class="line"><span>      primaryColor: string;</span></span>
<span class="line"><span>      secondaryColor: string;</span></span>
<span class="line"><span>      accentColor: string;</span></span>
<span class="line"><span>      backgroundColor: string;</span></span>
<span class="line"><span>      surfaceColor: string;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>    typography: {</span></span>
<span class="line"><span>      fontFamily: string;</span></span>
<span class="line"><span>      baseFontSize: number;</span></span>
<span class="line"><span>      headingScale: number;</span></span>
<span class="line"><span>      lineHeight: number;</span></span>
<span class="line"><span>      letterSpacing: number;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>    layout: {</span></span>
<span class="line"><span>      borderRadius: number;</span></span>
<span class="line"><span>      spacing: number;</span></span>
<span class="line"><span>      maxWidth: number;</span></span>
<span class="line"><span>      gridGap: number;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>    components: {</span></span>
<span class="line"><span>      buttonStyle: &#39;filled&#39; | &#39;outlined&#39; | &#39;ghost&#39;;</span></span>
<span class="line"><span>      cardElevation: number;</span></span>
<span class="line"><span>      inputStyle: &#39;underline&#39; | &#39;outline&#39; | &#39;filled&#39;;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 预览器设计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  多页面预览：</span></span>
<span class="line"><span>  - 首页（Landing Page）</span></span>
<span class="line"><span>  - 产品页（Product Showcase）</span></span>
<span class="line"><span>  - 博客页（Blog Layout）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  响应式预览：</span></span>
<span class="line"><span>  - 手机（375px）</span></span>
<span class="line"><span>  - 平板（768px）</span></span>
<span class="line"><span>  - 桌面（1440px）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  主题切换：</span></span>
<span class="line"><span>  - 浅色模式</span></span>
<span class="line"><span>  - 深色模式</span></span>
<span class="line"><span>  - 自动跟随系统</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. AI生成引擎优化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  提示词结构：</span></span>
<span class="line"><span>  interface AIPrompt {</span></span>
<span class="line"><span>    basePrompt: string; // 来自bootstrap-prompt.txt</span></span>
<span class="line"><span>    styleConfig: StyleConfig;</span></span>
<span class="line"><span>    contentType: &#39;landing&#39; | &#39;product&#39; | &#39;blog&#39;;</span></span>
<span class="line"><span>    additionalRequirements: string[];</span></span>
<span class="line"><span>    authorInfo: {</span></span>
<span class="line"><span>      name: string;</span></span>
<span class="line"><span>      socialLinks: string[];</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  生成流程：</span></span>
<span class="line"><span>  1. 用户配置样式参数</span></span>
<span class="line"><span>  2. 系统生成标准化JSON配置</span></span>
<span class="line"><span>  3. 结合提示词调用AI接口</span></span>
<span class="line"><span>  4. 生成完整HTML模板</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. 用户界面设计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  左侧配置面板：</span></span>
<span class="line"><span>  ┌─────────────────────────────────────┐</span></span>
<span class="line"><span>  │ 预设模板选择器                      │</span></span>
<span class="line"><span>  ├─────────────────────────────────────┤</span></span>
<span class="line"><span>  │ 主题色彩配置                        │</span></span>
<span class="line"><span>  │ ├── 主色调  ■ #3B82F6               │</span></span>
<span class="line"><span>  │ ├── 辅助色  ■ #10B981               │</span></span>
<span class="line"><span>  │ └── 背景色  ■ #FFFFFF               │</span></span>
<span class="line"><span>  ├─────────────────────────────────────┤</span></span>
<span class="line"><span>  │ 字体排版设置                        │</span></span>
<span class="line"><span>  │ ├── 字体族  [Inter] ▼              │</span></span>
<span class="line"><span>  │ ├── 基础字号  16px [-][+]          │</span></span>
<span class="line"><span>  │ └── 行高     1.5 [-][+]            │</span></span>
<span class="line"><span>  ├─────────────────────────────────────┤</span></span>
<span class="line"><span>  │ 组件样式                            │</span></span>
<span class="line"><span>  │ ├── 按钮样式 [填充] ▼               │</span></span>
<span class="line"><span>  │ └── 圆角半径  8px [-][+]           │</span></span>
<span class="line"><span>  ├─────────────────────────────────────┤</span></span>
<span class="line"><span>  │ [🎲 随机生成] [💾 保存配置]         │</span></span>
<span class="line"><span>  └─────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  右侧预览面板：</span></span>
<span class="line"><span>  ┌─────────────────────────────────────┐</span></span>
<span class="line"><span>  │ [首页] [产品] [博客] | 📱 💻 🖥️ 🌓 │</span></span>
<span class="line"><span>  ├─────────────────────────────────────┤</span></span>
<span class="line"><span>  │                                     │</span></span>
<span class="line"><span>  │         实时预览区域                 │</span></span>
<span class="line"><span>  │                                     │</span></span>
<span class="line"><span>  │    ╔═══════════════════════╗       │</span></span>
<span class="line"><span>  │    ║                       ║       │</span></span>
<span class="line"><span>  │    ║   模板预览内容         ║       │</span></span>
<span class="line"><span>  │    ║                       ║       │</span></span>
<span class="line"><span>  │    ╚═══════════════════════╝       │</span></span>
<span class="line"><span>  │                                     │</span></span>
<span class="line"><span>  └─────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. 技术实现方案</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  前端架构：</span></span>
<span class="line"><span>  - Vue 3 Composition API</span></span>
<span class="line"><span>  - Naive UI组件库</span></span>
<span class="line"><span>  - UnoCSS样式框架</span></span>
<span class="line"><span>  - Pinia状态管理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  配置持久化：</span></span>
<span class="line"><span>  - LocalStorage保存用户配置</span></span>
<span class="line"><span>  - 支持导出/导入JSON配置</span></span>
<span class="line"><span>  - 版本管理支持</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  AI集成：</span></span>
<span class="line"><span>  - 封装通用AI调用接口</span></span>
<span class="line"><span>  - 支持多种AI服务提供商</span></span>
<span class="line"><span>  - 缓存机制优化性能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7. 交互优化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  用户体验增强：</span></span>
<span class="line"><span>  - 配置变更实时预览</span></span>
<span class="line"><span>  - 撤销/重做功能</span></span>
<span class="line"><span>  - 键盘快捷键支持</span></span>
<span class="line"><span>  - 拖拽调整参数</span></span>
<span class="line"><span>  - 批量应用样式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  性能优化：</span></span>
<span class="line"><span>  - 虚拟滚动长列表</span></span>
<span class="line"><span>  - 防抖处理频繁操作</span></span>
<span class="line"><span>  - 懒加载预览内容</span></span>
<span class="line"><span>  - 压缩传输数据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>8. 扩展功能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  高级功能：</span></span>
<span class="line"><span>  - 自定义CSS注入</span></span>
<span class="line"><span>  - JavaScript交互增强</span></span>
<span class="line"><span>  - SEO优化配置</span></span>
<span class="line"><span>  - 性能指标监控</span></span>
<span class="line"><span>  - A/B测试支持</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这个设计方案充分考虑了用户友好性、技术可行性和扩展性，能够满足内容管理系统中AI生成站点模板的核心需求。</span></span></code></pre></div><p>当时感觉已经和细化了，特别是有同事提到的 ascii 的 ui，于是让 Claude 继续生成。</p><p><em>（此处配图缺失）</em></p><p>一开始生成的页面是这样的，配置在左侧，Prompt在下面，不是太好的利用页面，于是让大模型把配置和提示词配置都放到右侧，用Tab 进行切换。</p><p>接下来发现一些交互的问题，直接发给Claude 进行修改。</p><p><img src="`+e+'" alt="image-20250918230352310"></p><p>在这个过程中当中，注意即使提交 Git，以保留修改的成果，毕竟 AI 生成的也还是有些随机。另外一个就是因为项目是由 lint check的，如果 Claude 自己不能修改的情况，可以用 ROO CODE。一个模型发现不了的问题，另一个模型能发现。</p><p>整个环境验证下拉自己基本没有写代码，都是交给了 Claude Code 插件来处理的。</p><p>下面是完成这个功能，修改其中的BUG，产生的消费记录。</p><p><img src="'+i+'" alt="image-20250918230945685"></p><p>通过这次AI 代码生成工具使用方法的调整，让我实现了一些我之前肯定做不出来的效果，而且我也基本上没有写代码，更重要的省钱省时间。</p>',28)])])}const h=n(c,[["render",t]]);export{C as __pageData,h as default};
